def strategy(history, rng):
    n = len(history)
    if n >= 99:
        return 'D'
    if n == 0:
        return 'C'

    last_me, last_opp = history[-1]

    opp_c = 0
    opp_d = 0
    cd = 0
    for m, o in history:
        if o == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if m == 'C' and o == 'D':
            cd += 1

    w = 12 if n >= 12 else n
    recent = history[-w:]
    rec_d = 0
    rec_cd = 0
    for m, o in recent:
        if o == 'D':
            rec_d += 1
        if m == 'C' and o == 'D':
            rec_cd += 1

    dd = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            dd += 1
        else:
            break

    if (opp_d >= opp_c + 3 or
        (n >= 12 and rec_d >= 9) or
        (rec_cd >= 5 and rec_d >= 7)):
        if (dd >= 3 and
            opp_d < opp_c + 7 and
            rec_d <= 7 and
            rec_cd <= 4):
            return 'C'
        return 'D'

    if last_opp == 'C':
        return 'C'

    if last_me == 'D':
        if dd >= 2 and rec_cd <= 3 and rec_d <= 6:
            return 'C'
        return 'D'

    if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C':
        if cd <= 3 and rec_d <= 6:
            return 'C'
        return 'D'

    return 'D'
